export function isSectionLegal(threadType: ThreadType, section: ArchiveState): boolean {
  return (LEGAL_SECTIONS[threadType] as readonly string[]).includes(section);
}

export function displaySection(
  stored: ArchiveState,
  status: ThreadStatus,
  isSaved: boolean,
  hasActiveChildren: boolean,
  hasPendingChanges: boolean,
  hasAttentionDescendants: boolean,
): DisplaySection {
  if (isSaved) return 'saved';
  const demandsSurface = status === 'running' || hasActiveChildren || hasPendingChanges || hasAttentionDescendants;
  if (stored === 'archived' && !demandsSurface) return 'archive';
  return 'current';
}

export function isCcOnlyEvent(eventType: string): boolean {
  return CC_ONLY_EVENTS.has(eventType);
}

export function availableThreadActions(
  threadType: ThreadType,
  status: ThreadStatus,
  storedSection: ArchiveState,
  hasPendingChanges: boolean,
  descendantsBlockArchive: boolean,
  hasLiveEventWaits: boolean,
  hasUnsentDraft: boolean,
  isSaved: boolean,
): Action[] {
  const actions: Action[] = [];
  const live = status === 'running' || status === 'waiting_for_user_answer';
  const codingAgentPending = hasPendingChanges && threadType === 'claude_code';
  if (hasUnsentDraft) actions.push('discard_draft');
  if (!live) {
    if (codingAgentPending) {
      if (!hasLiveEventWaits) actions.push('discard', 'apply', 'set_aside');
    } else if (storedSection === 'inbox' && !descendantsBlockArchive) {
      actions.push('archive');
    }
  }
  const watching = hasLiveEventWaits && status !== 'waiting_for_user_answer' && status !== 'failed';
  if (threadType === 'claude_code' && (status === 'running' || status === 'paused' || watching)) {
    actions.push('apply_when_settled');
  }
  actions.push(isSaved ? 'unsave' : 'save');
  return actions;
}

export type OwnBlocker = 'running' | 'question' | 'pending_change' | 'held_proposal';
export const OWN_BLOCKER_PRIORITY: readonly OwnBlocker[] = ['running', 'question', 'pending_change', 'held_proposal'] as const;
export type Blocker = 'none' | 'home' | 'running' | 'question' | 'pending_change' | 'held_proposal' | 'descendant_running' | 'descendant_question' | 'descendant_pending_change' | 'descendant_held_proposal';

export type ChangeWork = 'none' | 'proposed' | 'held';

export type ChangeStateKind = 'none' | 'unproposed' | 'proposed';

export function changeWork(
  change: ChangeStateKind,
  holdsLiveWait: boolean,
): ChangeWork {
  if (change === 'proposed') return 'proposed';
  return change === 'unproposed' && holdsLiveWait ? 'held' : 'none';
}

export function ownBlocker(
  threadType: ThreadType,
  status: ThreadStatus,
  archiveState: ArchiveState,
  change: ChangeWork,
  isExternalRepo: boolean,
): OwnBlocker | null {
  if (status === 'running') return 'running';
  if (status === 'waiting_for_user_answer') return 'question';
  if (archiveState === 'archived' || threadType !== 'claude_code' || isExternalRepo) return null;
  if (change === 'proposed') return 'pending_change';
  return change === 'held' ? 'held_proposal' : null;
}

export function actionBlocker(
  own: OwnBlocker | null,
  isHome: boolean,
  descendant: OwnBlocker | null,
): Blocker {
  if (isHome) return 'home';
  if (own !== null) return own;
  if (descendant !== null) return `descendant_${descendant}`;
  return 'none';
}
